#!/usr/bin/env python3
import re
import subprocess
import sys

def parse_duration(text: str):
    m = re.search(r"Duration:\s*(\d+):(\d+):(\d+(?:\.\d+)?)", text)
    if not m:
        return None
    h, mi, s = int(m.group(1)), int(m.group(2)), float(m.group(3))
    return h * 3600 + mi * 60 + s


def main():
    video_path = None
    for a in reversed(sys.argv[1:]):
        if not a.startswith("-"):
            video_path = a
            break
    if not video_path:
        return 1

    proc = subprocess.run(["ffmpeg", "-hide_banner", "-i", video_path], capture_output=True, text=True)
    dur = parse_duration(proc.stderr) or parse_duration(proc.stdout)
    if dur is None:
        return 1
    sys.stdout.write(f"{dur}\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
